import classNames from 'classnames';

const buildContainerProps = (gapBetweenHeaderAndItems, sideMargin) => ({
    className: 'flex flex-col',
    style: {
        gap: gapBetweenHeaderAndItems,
        marginLeft: sideMargin ?? 0,
        marginRight: sideMargin ?? 0
    }
});
const buildViewportProps = (scrollArrowOffset, scrollArrowBackgroundColor, scrollArrowBoxShadowColor) => ({
    className: 'relative',
    style: {
        '--sdui-cc-arrow-offset': `${scrollArrowOffset}px`,
        ...(scrollArrowBackgroundColor ? { '--sdui-cc-arrow-bg': scrollArrowBackgroundColor } : {}),
        ...(scrollArrowBoxShadowColor ? { '--sdui-cc-arrow-shadow': scrollArrowBoxShadowColor } : {})
    }
});
const buildTrackProps = (columnGap, shouldUseHorizontalScroll) => ({
    className: classNames('flex', 
    // Keep a non-scrollable carousel clipped. overflow-x:auto would let a
    // trackpad or shift-wheel reveal tiles that arrows and impressions ignore.
    shouldUseHorizontalScroll ? '[overflow-x:auto]' : '[overflow-x:hidden]', '[-webkit-overflow-scrolling:touch]', '[-ms-overflow-style:none]', '[scrollbar-width:none]', '[&::-webkit-scrollbar]:hidden'),
    style: {
        scrollSnapType: 'x mandatory',
        scrollBehavior: 'smooth',
        gap: columnGap ?? 0
    }
});
const buildPreMeasureItemWidth = (numTilesToFit, columnGap) => {
    const gapCount = Math.max(Math.ceil(numTilesToFit) - 1, 0);
    const gapPx = columnGap * gapCount;
    return `calc((100% - ${gapPx}px) / ${numTilesToFit})`;
};
/**
 * Before ResizeObserver reports a width (SSR / first client paint), `itemWidth` is 0,
 * which would collapse tiles. In that case size them as a calc fraction of the
 * track using `numTilesToFit`. That divisor is accurate when column count comes from
 * a measured or estimated container width (or `numColumnsOverride`); without either,
 * it falls back to `minItemCount` and wide viewports may still shrink after measure.
 */
const buildItemStyle = (itemWidth, numTilesToFit, columnGap) => ({
    flexShrink: 0,
    width: itemWidth <= 0 && numTilesToFit > 0
        ? buildPreMeasureItemWidth(numTilesToFit, columnGap ?? 0)
        : itemWidth,
    height: 'auto'
});
// Logical inline-start/end so arrows mirror automatically under direction: rtl.
const buildScrollArrowClassName = (side, isVisible) => classNames('absolute', isVisible ? 'flex' : 'hidden', '[top:calc(50%-20px)]', side === 'prev'
    ? '[inset-inline-start:var(--sdui-cc-arrow-offset)]'
    : '[inset-inline-end:var(--sdui-cc-arrow-offset)]', '[width:40px]', '[height:40px]', '[border-radius:50%]', '[justify-content:center]', '[align-items:center]', '[cursor:pointer]', '[z-index:5]', '[opacity:0.9]', 'hover:[opacity:1]', '[background-color:var(--sdui-cc-arrow-bg)]', '[box-shadow:0px_0px_4px_0px_var(--sdui-cc-arrow-shadow)]');

export { buildContainerProps, buildItemStyle, buildScrollArrowClassName, buildTrackProps, buildViewportProps };
